-- ============================================================================
-- VOLTNET ENTERPRISE DATABASE SEEDING SCRIPT (dataseed.sql)
-- Context: Real Gujarat EV Infrastructure (50% Kutch, 50% Anand)
-- Authentication: Password for all accounts is '123'
-- Users: Realistic diverse Indian names with shivam / hritik email series
-- Safety: Preserves AdminUsers table entirely (Admin table is not touched)
-- ============================================================================
SET NOCOUNT ON;
GO

-- 1. DISABLE ALL FOREIGN KEY CONSTRAINTS
PRINT 'Disabling foreign key constraints...';
EXEC sp_MSforeachtable 'ALTER TABLE ? NOCHECK CONSTRAINT all';
GO

-- 2. CLEANUP ALL OPERATIONAL DATA TABLES (EXCEPT AdminUsers & SubscriptionPlans)
PRINT 'Cleaning operational tables...';
DELETE FROM [StationOwnerDocuments];
DELETE FROM [StationDocuments];
DELETE FROM [MaintenanceTickets];
DELETE FROM [Vehicles];
DELETE FROM [StationBlockSlots];
DELETE FROM [WaitlistEntries];
DELETE FROM [Bookings];
DELETE FROM [ChargingRates];
DELETE FROM [Chargers];
DELETE FROM [StationManagers];
DELETE FROM [Stations];
DELETE FROM [OwnerSubscriptions];
DELETE FROM [StationOwners];
DELETE FROM [UserMaster];
GO

-- 3. ENSURE SUBSCRIPTION PLANS EXIST
PRINT 'Ensuring Subscription Plans exist...';
IF NOT EXISTS (SELECT 1 FROM SubscriptionPlans WHERE id = '0c4d9979-9bbc-41c4-bd87-034006432be6')
INSERT INTO SubscriptionPlans (id, name, description, price_per_month, max_stations, max_managers_per_station, duration_days, is_active, created_at)
VALUES ('0c4d9979-9bbc-41c4-bd87-034006432be6', 'Starter', 'Ideal for single-station independent station hosts.', 999.00, 1, 2, 30, 1, GETUTCDATE());

IF NOT EXISTS (SELECT 1 FROM SubscriptionPlans WHERE id = '1cb27374-ef98-4c4f-b101-0ae641f91092')
INSERT INTO SubscriptionPlans (id, name, description, price_per_month, max_stations, max_managers_per_station, duration_days, is_active, created_at)
VALUES ('1cb27374-ef98-4c4f-b101-0ae641f91092', 'Growth', 'Best for expanding regional EV charging networks.', 3999.00, 5, 5, 30, 1, GETUTCDATE());

IF NOT EXISTS (SELECT 1 FROM SubscriptionPlans WHERE id = 'c7e5e1ab-091e-4c57-85ce-c782c3fc1d7e')
INSERT INTO SubscriptionPlans (id, name, description, price_per_month, max_stations, max_managers_per_station, duration_days, is_active, created_at)
VALUES ('c7e5e1ab-091e-4c57-85ce-c782c3fc1d7e', 'Enterprise', 'Full-fleet enterprise tier for commercial charging hubs.', 9999.00, 20, 10, 30, 1, GETUTCDATE());
GO

