-- 13. VERIFICATION SUMMARY
PRINT '==================================================';
PRINT 'VOLTNET SEEDING COMPLETED SUCCESSFULLY!';
PRINT 'Summary of Seeded Records:';
SELECT 'AdminUsers (Untouched)' AS [Table], COUNT(*) AS [Rows] FROM AdminUsers
UNION ALL SELECT 'UserMaster Total', COUNT(*) FROM UserMaster
UNION ALL SELECT 'StationOwners', COUNT(*) FROM StationOwners
UNION ALL SELECT 'OwnerSubscriptions', COUNT(*) FROM OwnerSubscriptions
UNION ALL SELECT 'Stations Total', COUNT(*) FROM Stations
UNION ALL SELECT 'Stations (Kutch 50%)', COUNT(*) FROM Stations WHERE city IN ('Bhuj', 'Gandhidham', 'Mundra', 'Anjar', 'Mandvi', 'Nakhatrana')
UNION ALL SELECT 'Stations (Anand 50%)', COUNT(*) FROM Stations WHERE city IN ('Anand', 'Vallabh Vidyanagar', 'Karamsad', 'Borsad', 'Khambhat', 'Petlad', 'Umreth')
UNION ALL SELECT 'Chargers Total', COUNT(*) FROM Chargers
UNION ALL SELECT 'ChargingRates Total', COUNT(*) FROM ChargingRates
UNION ALL SELECT 'StationManagers Total', COUNT(*) FROM StationManagers
UNION ALL SELECT 'Vehicles Total', COUNT(*) FROM Vehicles
UNION ALL SELECT 'Bookings Total', COUNT(*) FROM Bookings
UNION ALL SELECT 'WaitlistEntries', COUNT(*) FROM WaitlistEntries
UNION ALL SELECT 'StationBlockSlots', COUNT(*) FROM StationBlockSlots
UNION ALL SELECT 'MaintenanceTickets', COUNT(*) FROM MaintenanceTickets;
GO
